// ============================================================
// 2. GRADES E STATUS DO EXPORT
// ============================================================
var colection_fv = ee.FeatureCollection(asset_photovoltaica);

// Asset pré-filtrado pelo setup_grades_rural.py (já tem 'quantidade').
// Se não estiver acessível, troque pela linha comentada abaixo.
var grades = ee.FeatureCollection(asset_grade_fv);
// var grades = ee.FeatureCollection(asset_grade).filterBounds(colection_fv);

var listConf = ee.List(IDS_CONFIRMADAS);
var listSub  = ee.List(IDS_SEM_CONFIRMACAO);

grades = grades.map(function(feat) {
    var sid = feat.get('system:index');
    var status = ee.Algorithms.If(listConf.contains(sid), 2,
                 ee.Algorithms.If(listSub.contains(sid), 1, 0));
    return feat.set('status_export', status);
});

// ============================================================
// 3. PREDIÇÕES NO GEE
// ============================================================
var preds = ee.ImageCollection(asset_predicoes);
if (ASSET_PRED_RURAL !== '') {
    preds = preds.merge(ee.ImageCollection(ASSET_PRED_RURAL));
}
print("saber quantas imagens tem o predict ", preds);
// var predsRural = preds.filterBounds(grades);
var predsYear  = preds.filter(ee.Filter.eq('year', YEAR));

print('Predições totais na coleção', preds.size());
print('Predições que tocam grades rurais (todos os anos)', predsYear.size());
print('Predições que tocam grades rurais (' + YEAR + ')', predsYear.size());
print('  por ano',      predsYear.aggregate_histogram('year'));
print('  por modelo',   predsYear.aggregate_histogram('modelo'));
print('  por backbone', predsYear.aggregate_histogram('backbone'));
print('  por version',  predsYear.aggregate_histogram('version'));
print('  exemplos',     predsYear.limit(5));

// print("saber quantas imagens tem o predict ", preds);
// Quantas imagens de predição (do YEAR) cobrem cada grade
grades = grades.map(function(feat) {
    var n = predsYear.filterBounds(feat.geometry()).size();
    return feat.set('n_pred', n, 'tem_pred', n.gt(0));
});

// ============================================================
// 4. RESUMO
// ============================================================
print('Grades com FV rural', grades.size());
print('Status export (2=confirmada, 1=sem confirmação, 0=não submetida)',
      grades.aggregate_histogram('status_export'));
print('Grades com predição ' + YEAR + ' (1=sim, 0=não)',
      grades.aggregate_histogram('tem_pred'));
print('Pontos FV em grades com predição',
      grades.filter(ee.Filter.eq('tem_pred', 1)).aggregate_sum('quantidade'));
print('Pontos FV em grades sem predição',
      grades.filter(ee.Filter.eq('tem_pred', 0)).aggregate_sum('quantidade'));
print('Top 20 grades SEM predição (mais pontos FV)',
      grades.filter(ee.Filter.eq('tem_pred', 0))
            .sort('quantidade', false).limit(20)
            .select(['quantidade', 'status_export']));

// ============================================================
// 5. MAPA
// ============================================================
var mosaic = ee.ImageCollection(asset_NICFI)
                .filter(ee.Filter.date(YEAR + '-07-01', YEAR + '-12-31'))
                .median();
Map.addLayer(mosaic, {bands: ['R', 'G', 'B'], min: 100, max: 3200, gamma: 1.8},
             'NICFI ' + YEAR, false);

// Contorno colorido por status do export
var outConf = ee.Image().byte().paint(grades.filter(ee.Filter.eq('status_export', 2)), 1, 2);
var outSub  = ee.Image().byte().paint(grades.filter(ee.Filter.eq('status_export', 1)), 1, 2);
var outNo   = ee.Image().byte().paint(grades.filter(ee.Filter.eq('status_export', 0)), 1, 2);
Map.addLayer(outConf, {palette: '00C000'}, 'Export: confirmada');
Map.addLayer(outSub,  {palette: 'FFD700'}, 'Export: sem confirmação', false);
Map.addLayer(outNo,   {palette: 'FF0000'}, 'Export: não submetida', false);

// Preenchimento: grades com / sem predição
var fillPred = ee.Image().byte().paint(grades, 'tem_pred');
Map.addLayer(fillPred.selfMask(), {palette: '0066FF', opacity: 0.35},
             'Grade COM predição ' + YEAR, false);
Map.addLayer(fillPred.eq(0).selfMask(), {palette: 'FF00FF', opacity: 0.35},
             'Grade SEM predição ' + YEAR, false);

// Pixels de predição
Map.addLayer(predsYear.mosaic(), {min: 0, max: 1, palette: ['#FF0000']},
             'Predição ' + YEAR);//.selfMask() 
Map.addLayer(colection_fv, {color: 'red'}, 'Pontos FV rural', false);

// Map.centerObject(grades, 5);

// Clique na grade: mostra propriedades
Map.onClick(function(coords) {
    var pt  = ee.Geometry.Point([coords.lon, coords.lat]);
    var sel = grades.filterBounds(pt);
    print('Grade clicada', sel.select(['quantidade', 'status_export', 'n_pred']));
    print('Predições na grade', predsYear.filterBounds(pt)
                                    .select([]).limit(10));
});

// ============================================================
// 6. EXPORT OPCIONAL (tabela de status para o Drive)
// ============================================================
Export.table.toDrive({
    collection: grades.select(['quantidade', 'status_export', 'n_pred', 'tem_pred'],
                              null, false),
    description: 'status_grades_rural_export_predict_' + YEAR,
    fileFormat: 'CSV'
});

// ============================================================
// 7. POLÍGONOS / PONTOS DE REVISÃO DO PREDICT → ASSET
// ------------------------------------------------------------
// Imports (Drawing Tools), todos do tipo FeatureCollection:
//   fv_confirm : retângulos — predict CORRETO na área (verdadeiro positivo)
//   fv_false   : retângulos — predict ERRADO na área (falso positivo)
//   incompleto : PONTOS sobre painéis que o predict NÃO detectou (omissão)
//
// Base de treino (TFRecord, rótulo = camada 'Predição YEAR' acima,
// zerada dentro de fv_false):
//   src/preprocessing/download_dataset_tfrecord_fv_revisao.py  ← fv_confirm, fv_false
// Base de inspeção (TIF sem rótulo, quadrado de ~500 m p/ cada lado do ponto):
//   src/preprocessing/download_tif_fv_omissao.py               ← incompleto
// Spec: docs/specs/download_dataset_tfrecord_fv_revisao.md
// ============================================================
var ASSET_OUT_REVISAO = 'projects/mapbiomas-arida/energias';
var VERSAO_REVISAO    = '22_11_2026';   // sufixo de data/versão no nome do asset
var BUFFER_OMISSAO_M  = 500;            // só para visualizar o recorte do TIF

// Adiciona metadados a cada feição do import.
// IMPORTANTE: exportar a FC retornada (não o import cru) — o Python filtra por 'year'.
var revisaoParaFC = function(importado, tipo, classe) {
    var fc = ee.FeatureCollection(importado);
    return ee.FeatureCollection(fc.toList(fc.size()).map(function(f) {
        f = ee.Feature(f);
        var g = f.geometry();
        return ee.Feature(g, {
            'tipo':    tipo,          // 'confirm' | 'false' | 'omissao'
            'classe':  classe,        // 1 = predict correto, 0 = falso positivo, -1 = omissão (sem rótulo)
            'year':    YEAR,
            'area_ha': g.area(1).divide(10000),   // 0 para pontos
            'versao':  VERSAO_REVISAO
        });
    }));
};

var exportarRevisao = function(fc, tipo) {
    var nameAsset = 'fv_' + tipo + '_' + YEAR + '_' + VERSAO_REVISAO;
    Export.table.toAsset({
        collection:  fc,
        description: nameAsset,
        assetId:     ASSET_OUT_REVISAO + '/' + nameAsset
    });
    print('Export → ' + ASSET_OUT_REVISAO + '/' + nameAsset, fc.size());
};

// typeof evita erro quando a camada ainda não foi desenhada
if (typeof fv_confirm !== 'undefined') {
    var fcConfirm = revisaoParaFC(fv_confirm, 'confirm', 1);
    Map.addLayer(ee.Image().byte().paint(fcConfirm, 1, 2), {palette: '00FF00'},
                 'fv_confirm (VP)');
    print('fv_confirm', fcConfirm.size(), 'ha', fcConfirm.aggregate_sum('area_ha'));
    exportarRevisao(fcConfirm, 'confirm');
} else {
    print('⚠️ camada fv_confirm não encontrada nos Imports');
}

if (typeof fv_false !== 'undefined') {
    var fcFalse = revisaoParaFC(fv_false, 'false', 0);
    Map.addLayer(ee.Image().byte().paint(fcFalse, 1, 2), {palette: 'FF8800'},
                 'fv_false (FP)');
    // como o rótulo vai ficar: predição zerada dentro de fv_false
    var labelPreview = predsYear.mosaic().gt(0).unmask(0)
                           .where(ee.Image(0).paint(fcFalse, 1).eq(1), 0);
    Map.addLayer(labelPreview.selfMask(), {palette: ['00FFFF']}, 'Rótulo TFRecord (preview)', false);
    print('fv_false', fcFalse.size(), 'ha', fcFalse.aggregate_sum('area_ha'));
    exportarRevisao(fcFalse, 'false');
} else {
    print('⚠️ camada fv_false não encontrada nos Imports');
}

if (typeof incompleto !== 'undefined') {
    var fcOmissao = revisaoParaFC(incompleto, 'omissao', -1);
    var recortes  = fcOmissao.map(function(f) {
        return f.buffer(BUFFER_OMISSAO_M).bounds();   // quadrado ~1 km do TIF
    });
    Map.addLayer(ee.Image().byte().paint(recortes, 1, 2), {palette: 'FF00FF'},
                 'Omissão: recorte TIF (~' + BUFFER_OMISSAO_M + ' m)');
    Map.addLayer(fcOmissao, {color: 'FF00FF'}, 'Omissão (pontos)');
    print('omissão (pontos)', fcOmissao.size());
    exportarRevisao(fcOmissao, 'omissao');
} else {
    print('⚠️ camada incompleto (omissão) não encontrada nos Imports');
}
